from collections import defaultdict, deque

def bfs(graph, start, end):
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        node, dist = queue.popleft()
        if node == end:
            return dist
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))
    return float('inf')

def find_best_word_to_add(words, start, end):
    n = len(words)
    word_length = len(start)

    # Create a graph where each word points to words that differ by one letter
    graph = defaultdict(set)
    for i in range(n):
        for j in range(i + 1, n):
            diff_count = sum(1 for a, b in zip(words[i], words[j]) if a != b)
            if diff_count == 1:
                graph[words[i]].add(words[j])
                graph[words[j]].add(words[i])

    # Check if we can reach the end without adding any word
    min_steps = bfs(graph, start, end)
    if min_steps != float('inf'):
        return "0", min_steps

    # Try adding each possible word and check the new shortest path
    best_word = None
    best_steps = float('inf')

    for i in range(word_length):
        for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
            new_word = start[:i] + c + start[i+1:]
            if new_word not in words and new_word != start:
                # Add the new word to the graph
                for word in words:
                    diff_count = sum(1 for a, b in zip(new_word, word) if a != b)
                    if diff_count == 1:
                        graph[new_word].add(word)
                        graph[word].add(new_word)

                # Check the shortest path with the new word added
                steps = bfs(graph, start, new_word) + bfs(graph, new_word, end)
                if steps < best_steps:
                    best_steps = steps
                    best_word = new_word

                # Remove the new word from the graph for the next iteration
                for word in words:
                    if diff_count == 1:
                        graph[new_word].remove(word)
                        graph[word].remove(new_word)

    if best_word is None:
        return "0", -1
    else:
        return best_word, best_steps

